module::ribbon.signature:
fn ribbon<K: FusionScalar>(
    ring: FusionRing,
    f: FSymbols<K>,
    r: RSymbols<K>,
    dimensions: Vec<K>,
) -> Result<RibbonFusionCategory<K>, FusionError>

module::ribbon.body:
{
    let category = FusionCategory::new(ring, f)?;
    RibbonFusionCategory::try_new(BraidedFusionCategory::new(category, r)?, dimensions)
}

module::ising.body:
{
    let ring = FusionRing::ising()?;
    let sqrt2 = sqrt_two::<K>()?;
    let f = ising_f(&ring, &sqrt2)?;
    let r = ising_r(&ring)?;
    ribbon(ring, f, r, vec![K::one(), sqrt2, K::one()])
}

module::ising_f.body:
{
    let inverse = omega_number_theory::scalar::inverse(sqrt2).map_err(FusionError::from)?;
    let negative = inverse.neg();
    let minus_one = K::one().neg();
    FSymbols::from_fn(ring, |labels, e, f| match (labels, e, f) {
        ([1, 1, 1, 1], 2, 2) => negative.clone(),
        ([1, 1, 1, 1], _, _) => inverse.clone(),
        ([1, 2, 1, 2] | [2, 1, 2, 1], _, _) => minus_one.clone(),
        _ => K::one(),
    })
}

module::ising_r.body:
{
    let minus_1 = root_of_unity::<K>(16, -1)?;
    let three = root_of_unity::<K>(16, 3)?;
    let minus_i = root_of_unity::<K>(16, 4)?.neg();
    let minus_one = K::one().neg();
    RSymbols::from_fn(ring, |labels| match labels {
        [1, 1, 0] => minus_1.clone(),
        [1, 1, 2] => three.clone(),
        [1, 2, 1] | [2, 1, 1] => minus_i.clone(),
        [2, 2, 0] => minus_one.clone(),
        _ => K::one(),
    })
}

module::fibonacci.body:
{
    let ring = FusionRing::fibonacci()?;
    let phi = golden_ratio::<K>()?;
    let f = fibonacci_f(&ring, &phi)?;
    let r = fibonacci_r(&ring)?;
    ribbon(ring, f, r, vec![K::one(), phi])
}

module::fibonacci_f.body:
{
    let inverse = phi.sub(&K::one());
    let negative = inverse.neg();
    FSymbols::from_fn(ring, |labels, e, f| match (labels, e, f) {
        ([1, 1, 1, 1], 0, 0) | ([1, 1, 1, 1], 1, 0) => inverse.clone(),
        ([1, 1, 1, 1], 1, 1) => negative.clone(),
        _ => K::one(),
    })
}

module::fibonacci_r.body:
{
    let minus_four = root_of_unity::<K>(10, -4)?;
    let three = root_of_unity::<K>(10, 3)?;
    RSymbols::from_fn(ring, |labels| match labels {
        [1, 1, 0] => minus_four.clone(),
        [1, 1, 1] => three.clone(),
        _ => K::one(),
    })
}

module::semion.body:
{
    let ring = FusionRing::semion()?;
    let minus_one = K::one().neg();
    let f = FSymbols::from_fn(&ring, |labels, _, _| {
        if labels == [1, 1, 1, 1] {
            minus_one.clone()
        } else {
            K::one()
        }
    })?;
    let i = root_of_unity::<K>(4, 1)?;
    let r = RSymbols::from_fn(&ring, |labels| {
        if labels == [1, 1, 0] {
            i.clone()
        } else {
            K::one()
        }
    })?;
    ribbon(ring, f, r, vec![K::one(), K::one()])
}

module::pointed_braided.body:
{
    let group = AbelianGroup::new(moduli)?;
    check_exponent_shape(exponents, moduli.len())?;
    let plan = PhasePlan::new(moduli, exponents);
    let order = group.order();
    let ring = FusionRing::pointed(moduli, names)?;
    // Admit the actual root subgroup before expensive symbol construction.
    let roots = phase_roots::<K>(plan.order)?;
    let digits = (0..order)
        .map(|x| group.digits(x))
        .collect::<Result<Vec<_>, _>>()?;
    let f = FSymbols::trivial(&ring)?;
    let r = RSymbols::from_fn(&ring, |[x, y, _]| {
        roots[plan.exponent(&digits[x], &digits[y])].clone()
    })?;
    ribbon(ring, f, r, (0..order).map(|_| K::one()).collect())
}

module::check_exponent_shape.body:
{
    if exponents.len() != factors {
        return Err(FusionError::ListLength {
            what: "rows of bicharacter exponents",
            expected: factors,
            got: exponents.len(),
        });
    }
    if let Some(row) = exponents.iter().find(|row| row.len() != factors) {
        return Err(FusionError::ListLength {
            what: "columns of bicharacter exponents",
            expected: factors,
            got: row.len(),
        });
    }
    Ok(())
}

module::gcd.body:
{
    while b != 0 {
        (a, b) = (b, a % b);
    }
    a
}

module::reduced_coefficient.body:
{
    // Private admitted moduli are 2..=32; the residue is at most 31.
    let denominator = gcd(left, right);
    let numerator = coefficient.rem_euclid(denominator as i64) as usize;
    let common = gcd(numerator, denominator);
    (numerator / common, denominator / common)
}

PhasePlan::new.body:
{
        // Caller established product(moduli)<=32 and the square exponent shape.
        let mut order = 1;
        for (i, row) in exponents.iter().enumerate() {
            for (j, &coefficient) in row.iter().enumerate() {
                let (_, denominator) = reduced_coefficient(coefficient, moduli[i], moduli[j]);
                order = order / gcd(order, denominator) * denominator;
            }
        }
        let weights = exponents
            .iter()
            .enumerate()
            .map(|(i, row)| {
                row.iter()
                    .enumerate()
                    .map(|(j, &coefficient)| {
                        let (numerator, denominator) =
                            reduced_coefficient(coefficient, moduli[i], moduli[j]);
                        numerator * (order / denominator)
                    })
                    .collect()
            })
            .collect();
        Self { order, weights }
    }

PhasePlan::exponent.body:
{
        let mut total = 0;
        for (row, &x) in self.weights.iter().zip(left) {
            for (&weight, &y) in row.iter().zip(right) {
                total += weight * x * y;
            }
        }
        total % self.order
    }

module::phase_roots.body:
{
    let generator = root_of_unity::<K>(order as u32, 1)?;
    let mut roots = Vec::with_capacity(order);
    roots.push(K::one());
    for i in 1..order {
        let next = roots[i - 1].mul(&generator);
        roots.push(next);
    }
    Ok(roots)
}

module::quantum_double_cyclic.signature:
pub fn quantum_double_cyclic<K: FusionScalar>(
    n: usize,
) -> Result<RibbonFusionCategory<K>, FusionError>

module::quantum_double_cyclic.body:
{
    let i64_n = i64::try_from(n).map_err(|_| FusionError::Overflow {
        context: "the order of a quantum double",
    })?;
    if i64_n < 2 {
        return Err(FusionError::RankOutOfRange {
            rank: n,
            max: crate::fusion_ring::MAX_RANK,
        });
    }
    pointed_braided(&[n, n], &[vec![0, 1], vec![0, 0]], None)
}

ModularData::from_ribbon.body:
{
        let s_tilde = Self::ribbon_s_matrix(ribbon.ring(), ribbon.dimensions(), ribbon.twists())?;
        Ok(Self {
            ring: ribbon.ring().clone(),
            dimensions: ribbon.dimensions().to_vec(),
            twists: ribbon.twists().to_vec(),
            s_tilde,
            d_squared: ribbon.global_dimension_squared(),
            p_plus: ribbon.gauss_sum(),
        })
    }

ModularData::ribbon_s_matrix.signature:
fn ribbon_s_matrix(
        ring: &FusionRing,
        dimensions: &[K],
        twists: &[K],
    ) -> Result<BasicMatrix<K>, FusionError>

ModularData::ribbon_s_matrix.body:
{
        let n = ring.rank();
        let inverses = twists
            .iter()
            .map(|theta| omega_number_theory::scalar::inverse(theta).map_err(FusionError::from))
            .collect::<Result<Vec<_>, _>>()?;
        let weighted = dimensions
            .iter()
            .zip(twists)
            .map(|(d, t)| d.mul(t))
            .collect::<Vec<_>>();
        let duals = (0..n)
            .map(|b| ring.dual(b))
            .collect::<Result<Vec<_>, _>>()?;
        BasicMatrix::try_from_fn_result(n, n, |a, b| {
            let total = Self::fusion_sum(ring, a, duals[b], &weighted)?;
            Ok(total.mul(&inverses[a]).mul(&inverses[b]))
        })
    }

ModularData::add_multiple.body:
{
        match multiplicity {
            0 => Ok(total),
            1 => Ok(total.add(value)),
            _ => {
                let weight = omega_number_theory::scalar::from_i64::<K>(
                    i64::try_from(multiplicity).map_err(|_| FusionError::Overflow {
                        context: "embedding a fusion coefficient",
                    })?,
                );
                Ok(total.add(&weight.mul(value)))
            }
        }
    }

ModularData::fusion_sum.body:
{
        let mut total = K::zero();
        for (c, value) in values.iter().enumerate() {
            total = Self::add_multiple(total, value, ring.n(a, b, c))?;
        }
        Ok(total)
    }

ModularData::scaled_charge_conjugation.body:
{
        let n = self.rank();
        BasicMatrix::try_from_fn_result(n, n, |a, b| {
            Ok(if self.ring.dual(a)? == b {
                scale.clone()
            } else {
                K::zero()
            })
        })
    }

ModularData::scaled_identity.body:
{
        let n = self.rank();
        BasicMatrix::try_from_fn(n, n, |a, b| if a == b { scale.clone() } else { K::zero() })
            .map_err(FusionError::from)
    }

ModularData::first_difference.signature:
fn first_difference(
        left: &BasicMatrix<K>,
        right: &BasicMatrix<K>,
    ) -> Result<Option<(usize, usize)>, FusionError>

ModularData::first_difference.body:
{
        if left.shape() != right.shape() {
            return Err(FusionError::Shape {
                operation: "comparing modular matrices",
                left: left.shape(),
                right: right.shape(),
            });
        }
        for a in 0..left.rows() {
            for b in 0..left.cols() {
                if left.get_ref(a, b)? != right.get_ref(a, b)? {
                    return Ok(Some((a, b)));
                }
            }
        }
        Ok(None)
    }

ModularData::verify.body:
{
        if self.d_squared.is_zero() {
            return Err(FusionError::Modular(ModularDefect::ZeroGlobalDimension));
        }
        self.verify_symmetry()?;
        self.verify_nondegenerate()?;
        let squared = self.verify_square()?;
        self.verify_unitarity()?;
        self.verify_relation(&squared)?;
        self.verify_verlinde()
    }

ModularData::require_equal.signature:
fn require_equal(
        left: &BasicMatrix<K>,
        right: &BasicMatrix<K>,
        defect: impl FnOnce(usize, usize) -> ModularDefect,
    ) -> Result<(), FusionError>

ModularData::require_equal.body:
{
        if let Some((a, b)) = Self::first_difference(left, right)? {
            return Err(FusionError::Modular(defect(a, b)));
        }
        Ok(())
    }

ModularData::verify_symmetry.body:
{
        for a in 0..self.rank() {
            for b in a + 1..self.rank() {
                if self.s_tilde.get_ref(a, b)? != self.s_tilde.get_ref(b, a)? {
                    return Err(FusionError::Modular(ModularDefect::NotSymmetric { a, b }));
                }
            }
        }
        Ok(())
    }

ModularData::verify_nondegenerate.body:
{
        let rank = elimination::rank(&self.s_tilde).map_err(FusionError::from)?;
        if rank < self.rank() {
            return Err(FusionError::Modular(ModularDefect::Degenerate {
                rank,
                size: self.rank(),
            }));
        }
        Ok(())
    }

ModularData::verify_square.body:
{
        let squared = matrix::multiply(&self.s_tilde, &self.s_tilde).map_err(FusionError::from)?;
        Self::require_equal(
            &squared,
            &self.scaled_charge_conjugation(&self.d_squared)?,
            |a, b| ModularDefect::SSquared { a, b },
        )?;
        Ok(squared)
    }

ModularData::verify_unitarity.body:
{
        let actual = matrix::multiply(
            &self.s_tilde,
            &involution::adjoint(&self.s_tilde).map_err(FusionError::from)?,
        )
        .map_err(FusionError::from)?;
        Self::require_equal(&actual, &self.scaled_identity(&self.d_squared)?, |a, b| {
            ModularDefect::Unitarity { a, b }
        })
    }

ModularData::st_matrix.body:
{
        let n = self.rank();
        BasicMatrix::try_from_fn_result(n, n, |a, b| {
            Ok(self.s_tilde.get_ref(a, b)?.mul(&self.twists[b]))
        })
    }

ModularData::verify_relation.body:
{
        let st = self.st_matrix()?;
        let square = matrix::multiply(&st, &st).map_err(FusionError::from)?;
        let cube = matrix::multiply(&square, &st).map_err(FusionError::from)?;
        let expected = matrix::scale(squared, &self.p_plus).map_err(FusionError::from)?;
        Self::require_equal(&cube, &expected, |a, b| ModularDefect::Relation { a, b })
    }

ModularData::verify_verlinde.body:
{
        if let Some(&[a, b, c]) = self
            .ring
            .verlinde_defects(&self.s_tilde, &self.d_squared)?
            .first()
        {
            return Err(FusionError::Modular(ModularDefect::Verlinde { a, b, c }));
        }
        Ok(())
    }

ModularData::central_charge_mod_4.body:
{
        let ratio =
            omega_number_theory::scalar::divide(&self.p_plus.mul(&self.p_plus), &self.d_squared)
                .map_err(FusionError::from)?;
        let (n, k) = root_of_unity_data(&ratio).ok_or(FusionError::NotInSubfield {
            what: "p_+^2 / D^2",
            expected: "a root of unity",
        })?;
        Ok(Rational::new(
            BigInt::from(4 * u64::from(k)),
            BigInt::from(n),
        ))
    }

ModularData::central_charge_mod_8.body:
{
        if total_dimension.mul(total_dimension) != self.d_squared {
            return Err(FusionError::Modular(ModularDefect::WrongGlobalDimension));
        }
        match total_dimension.real_sign() {
            Some(Ordering::Greater) => {}
            Some(_) => return Err(FusionError::Modular(ModularDefect::NonPositiveDimension)),
            None => {
                return Err(FusionError::SignUndecided {
                    context: "the global dimension D",
                })
            }
        }
        let ratio = omega_number_theory::scalar::divide(&self.p_plus, total_dimension)
            .map_err(FusionError::from)?;
        let (n, k) = root_of_unity_data(&ratio).ok_or(FusionError::NotInSubfield {
            what: "p_+ / D",
            expected: "a root of unity",
        })?;
        Ok(Rational::new(
            BigInt::from(8 * u64::from(k)),
            BigInt::from(n),
        ))
    }

ModularData::frobenius_schur_indicator.body:
{
        let n = self.rank();
        if a >= n {
            return Err(FusionError::Label { label: a, rank: n });
        }
        let weights = self.indicator_weights()?;
        let mut total = K::zero();
        for b in 0..n {
            total = total.add(&self.indicator_row(a, b, &weights)?);
        }
        let value = omega_number_theory::scalar::divide(&total, &self.d_squared)
            .map_err(FusionError::from)?;
        Self::indicator_result(a, &value)
    }

ModularData::indicator_weights.body:
{
        self.dimensions
            .iter()
            .zip(&self.twists)
            .map(|(d, t)| {
                let square = t.mul(t);
                Ok((
                    d.mul(&square),
                    omega_number_theory::scalar::divide(d, &square).map_err(FusionError::from)?,
                ))
            })
            .collect()
    }

ModularData::indicator_row.body:
{
        let mut total = K::zero();
        for (c, (_, right)) in weights.iter().enumerate() {
            let multiplicity = self.ring.n(b, c, a);
            if multiplicity == 0 {
                continue;
            }
            total = Self::add_multiple(total, &weights[b].0.mul(right), multiplicity)?;
        }
        Ok(total)
    }

ModularData::indicator_result.body:
{
        if *value == K::one() {
            Ok(1)
        } else if *value == K::one().neg() {
            Ok(-1)
        } else if value.is_zero() {
            Ok(0)
        } else {
            Err(FusionError::Modular(ModularDefect::FrobeniusSchur {
                label: a,
            }))
        }
    }

ModularData::ground_state_degeneracy.body:
{
        let exponent = Self::genus_exponent(genus)?;
        let mut total = K::zero();
        for (ratio, multiplicity) in self.dimension_ratios()? {
            let value =
                omega_number_theory::scalar::power(&ratio, exponent).map_err(FusionError::from)?;
            total = Self::add_multiple(total, &value, multiplicity)?;
        }
        let rational = total.to_rational().ok_or(FusionError::NotInSubfield {
            what: "the ground-state degeneracy",
            expected: "a rational number",
        })?;
        if !rational.is_integer() || rational < Rational::from_integer(BigInt::from(0)) {
            return Err(FusionError::NotInSubfield {
                what: "the ground-state degeneracy",
                expected: "a non-negative integer",
            });
        }
        Ok(rational.to_integer())
    }

ModularData::genus_exponent.body:
{
        let exponent = i64::from(genus) - 1;
        let requested = exponent.unsigned_abs();
        let limit = omega_number_theory::scalar::MAX_SCALAR_EXPONENT;
        if requested > limit {
            return Err(FusionError::Budget {
                what: "ground-state exponent",
                requested: requested as u128,
                limit: limit as u128,
            });
        }
        Ok(exponent)
    }

ModularData::dimension_ratios.body:
{
        let mut squares: Vec<(K, u64)> = Vec::new();
        for d in &self.dimensions {
            let square = d.mul(d);
            if let Some((_, count)) = squares.iter_mut().find(|(s, _)| *s == square) {
                *count += 1;
            } else {
                squares.push((square, 1));
            }
        }
        for (square, _) in &mut squares {
            *square = omega_number_theory::scalar::divide(&self.d_squared, square)
                .map_err(FusionError::from)?;
        }
        Ok(squares)
    }
